import unittest
from inv import Item, total_value, format_report


class T(unittest.TestCase):
    def test_total(self):
        self.assertEqual(total_value([Item("a", 100, 3), Item("b", 250, 2)]), 800)

    def test_empty(self):
        self.assertEqual(total_value([]), 0)

    def test_report(self):
        items = [Item("pear", 1200, 1), Item("apple", 3000, 2)]
        self.assertEqual(format_report(items), "apple: 3,000 x 2\npear: 1,200 x 1\nTOTAL: 7,200")
